  if (rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel))) quit();
  if (fs.existsSync(path.join(root, '.no-autopush'))) quit();

  // 4. Repo state.
  const gitDir = git(root, ['rev-parse', '--absolute-git-dir']).out;
  if (!gitDir) quit();
